/// Every order the typestate API admits: at each of 12 steps, any
/// action whose inputs exist. The `assume` admits only those orders; the
/// types forbid the rest at compile time. Each I2C peripheral writes zero or
/// one byte when it starts; each SPI peripheral takes its bus's chip selects;
/// and the output pins are driven zero or one time first.
#[kani::proof]
#[kani::unwind(77)]
fn every_valid_sequence() {
    let mut img = Image {
        rcc: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let before = img;
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let mut gpioa = Some(board.gpioa);
    let mut gpiob = Some(board.gpiob);
    let mut i2c1 = Some(board.i2c1);
    let mut i2c1_clocked = None;
    let mut i2c1_done = false;
    let mut spi1 = Some(board.spi1);
    let mut spi1_clocked = None;
    let mut spi1_done = false;
    let mut i2c1_timingr = 0u32;
    let mut pa0 = None;
    let mut pa0_done = None;
    let mut pa5 = None;
    let mut pa5_done = None;
    let mut pa6 = None;
    let mut pa6_done = None;
    let mut pa7 = None;
    let mut pa7_done = None;
    let mut pb6 = None;
    let mut pb6_done = None;
    let mut pb7 = None;
    let mut pb7_done = None;
    for _ in 0..12 {
        let action: u8 = kani::any();
        match action {
            0 => {
                kani::assume(gpioa.is_some());
                let pins = rcc.enable_gpioa(&mut img, gpioa.take().unwrap()).split();
                pa0 = Some(pins.pa0);
                pa5 = Some(pins.pa5);
                pa6 = Some(pins.pa6);
                pa7 = Some(pins.pa7);
            }
            1 => {
                kani::assume(gpiob.is_some());
                let pins = rcc.enable_gpiob(&mut img, gpiob.take().unwrap()).split();
                pb6 = Some(pins.pb6);
                pb7 = Some(pins.pb7);
            }
            2 => {
                kani::assume(i2c1.is_some());
                i2c1_clocked = Some(rcc.enable_i2c1(&mut img, i2c1.take().unwrap()));
            }
            3 => {
                kani::assume(spi1.is_some());
                spi1_clocked = Some(rcc.enable_spi1(&mut img, spi1.take().unwrap()));
            }
            4 => {
                kani::assume(pa0.is_some());
                let mut pin = pa0.take().unwrap().into_output(&mut img);
                if kani::any() {
                    if kani::any() {
                        pin.set_low(&mut img);
                        kani::assert(img.gpioa[6] == 0x00010000, "PA0 set_low did not reset it");
                        kani::cover!(true, "PA0 driven low");
                    } else {
                        pin.set_high(&mut img);
                        kani::assert(img.gpioa[6] == 0x00000001, "PA0 set_high did not set it");
                        kani::cover!(true, "PA0 driven high");
                    }
                }
                pa0_done = Some(pin);
            }
            5 => {
                kani::assume(pa5.is_some());
                let pin = pa5.take().unwrap().into_spi1_sck(&mut img);
                pa5_done = Some(pin);
            }
            6 => {
                kani::assume(pa6.is_some());
                let pin = pa6.take().unwrap().into_spi1_miso(&mut img);
                pa6_done = Some(pin);
            }
            7 => {
                kani::assume(pa7.is_some());
                let pin = pa7.take().unwrap().into_spi1_mosi(&mut img);
                pa7_done = Some(pin);
            }
            8 => {
                kani::assume(pb6.is_some());
                let pin = pb6.take().unwrap().into_i2c1_scl(&mut img);
                pb6_done = Some(pin);
            }
            9 => {
                kani::assume(pb7.is_some());
                let pin = pb7.take().unwrap().into_i2c1_sda(&mut img);
                pb7_done = Some(pin);
            }
            10 => {
                kani::assume(i2c1_clocked.is_some() && pb6_done.is_some() && pb7_done.is_some());
                let i = i2c1_clocked.take().unwrap();
                let speed: u8 = kani::any();
                if speed == 0 {
                    i2c1_timingr = 0x10707dbc;
                    let mut bus = i.init::<i2c1_speed::Standard100k, _>(&mut img, pb6_done.take().unwrap(), pb7_done.take().unwrap());
                    kani::cover!(true, "I2C1 started at Standard100k");
                    if kani::any() {
                        let levels = [img.gpioa[6], img.gpiob[6]];
                        bus.write_byte(&mut img, kani::any());
                        kani::assert(levels == [img.gpioa[6], img.gpiob[6]], "I2C1 write_byte touched a GPIO BSRR");
                        kani::cover!(true, "I2C1 wrote a byte");
                    }
                } else {
                    i2c1_timingr = 0x00602173;
                    let mut bus = i.init::<i2c1_speed::Fast400k, _>(&mut img, pb6_done.take().unwrap(), pb7_done.take().unwrap());
                    kani::cover!(true, "I2C1 started at Fast400k");
                    if kani::any() {
                        let levels = [img.gpioa[6], img.gpiob[6]];
                        bus.write_byte(&mut img, kani::any());
                        kani::assert(levels == [img.gpioa[6], img.gpiob[6]], "I2C1 write_byte touched a GPIO BSRR");
                        kani::cover!(true, "I2C1 wrote a byte");
                    }
                }
                i2c1_done = true;
            }
            11 => {
                kani::assume(spi1_clocked.is_some() && pa5_done.is_some() && pa7_done.is_some() && pa6_done.is_some() && pa0_done.is_some());
                let i = spi1_clocked.take().unwrap();
                let _bus = i.init::<_>(&mut img, pa5_done.take().unwrap(), pa7_done.take().unwrap(), pa6_done.take().unwrap(), Spi1Selects { pa0: pa0_done.take().unwrap() });
                kani::cover!(true, "SPI1 started");
                spi1_done = true;
            }
            _ => kani::assume(false),
        }
    }
    kani::assert(i2c1_done, "the schedule did not start I2C1");
    kani::assert(spi1_done, "the schedule did not start SPI1");
    check_final(&before, &img, i2c1_timingr);
    kani::cover!(true, "the end of a complete schedule is reachable");
}

/// I2c1's registers as a transfer may touch them, in order. `stage` is 0 before
/// the first START, 1 in the write phase, 2 in the read phase, 3 after the
/// flags are cleared.
struct I2c1Spy {
    stage: u8,
    isr_reads: u32,
    bytes_written: usize,
}

impl sealed::Sealed for I2c1Spy {}

impl Registers for I2c1Spy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        kani::assert(block == Block::I2c1, "a I2c1 transfer read another block");
        if offset == 0x18 {
            kani::assert(self.stage >= 1, "ISR polled before the START");
            self.isr_reads += 1;
            kani::any()
        } else if offset == 0x24 {
            kani::assert(self.stage == 2, "RXDR read outside the read phase");
            kani::any()
        } else {
            kani::assert(false, "a I2c1 transfer read a register it does not own");
            0
        }
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        kani::assert(block == Block::I2c1, "a I2c1 transfer wrote another block");
        if offset == 0x04 {
            kani::assert(value & 0x00002000 != 0, "CR2 written without START");
            if value & 0x00000400 != 0 {
                kani::assert(self.stage <= 1, "the read phase did not follow the write phase");
                kani::assert(value & 0x02000000 != 0, "a read ends without AUTOEND");
                kani::assert(
                    self.stage == 0 || self.isr_reads as usize > self.bytes_written,
                    "the read phase began without waiting for TC",
                );
                self.stage = 2;
            } else {
                kani::assert(self.stage == 0, "the write phase is not first");
                self.stage = 1;
            }
        } else if offset == 0x28 {
            kani::assert(self.stage == 1, "TXDR written outside the write phase");
            self.bytes_written += 1;
        } else if offset == 0x1c {
            kani::assert(self.stage >= 1, "flags cleared before the START");
            kani::assert(value == 0x00000020 | 0x00000010, "ICR cleared more than STOPCF and NACKCF");
            self.stage = 3;
        } else {
            kani::assert(false, "a I2c1 transfer wrote a register it does not own");
        }
    }
    fn read8(&mut self, _: sealed::Token, _: Block, _: usize) -> u8 {
        kani::assert(false, "a I2c1 transfer made a byte access");
        0
    }
    fn write8(&mut self, _: sealed::Token, _: Block, _: usize, _: u8) {
        kani::assert(false, "a I2c1 transfer made a byte access");
    }
}

/// A transfer of any address, up to two bytes each way and any answers, with
/// each wait bounded at two reads of `ISR`: touches only I2c1, in order, within
/// the bound, and ends in the result its phases imply.
#[kani::proof]
#[kani::unwind(6)]
fn i2c1_transfer_is_bounded_and_ordered() {
    let mut img = Image {
        rcc: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let gpiob = rcc.enable_gpiob(&mut img, board.gpiob).split();
    let pb6 = gpiob.pb6.into_i2c1_scl(&mut img);
    let pb7 = gpiob.pb7.into_i2c1_sda(&mut img);
    let mut bus = rcc
        .enable_i2c1(&mut img, board.i2c1)
        .init::<i2c1_speed::Standard100k, _>(&mut img, pb6, pb7);
    let mut spy = I2c1Spy { stage: 0, isr_reads: 0, bytes_written: 0 };
    let (wl, rl): (usize, usize) = (kani::any(), kani::any());
    kani::assume(wl <= 2 && rl <= 2);
    let out: [u8; 2] = kani::any();
    let mut back = [0u8; 2];
    let spins = 2;
    let result = bus.transfer_within(&mut spy, kani::any(), &out[..wl], &mut back[..rl], spins);
    let waits = wl + usize::from(wl > 0 && rl > 0) + rl + usize::from(wl + rl > 0);
    kani::assert(
        spy.isr_reads as usize <= waits * spins as usize,
        "a wait read ISR more often than its bound",
    );
    kani::assert((wl + rl == 0) == (spy.stage == 0), "a transfer of nothing touched a register, or one of something did not");
    if wl + rl > 0 {
        kani::assert(spy.stage == 3, "a transfer did not end by clearing its flags");
    }
    match result {
        Ok(n) => {
            kani::assert(n == rl && spy.bytes_written == wl, "Ok without every byte moved");
            kani::cover!(wl > 0 && rl > 0, "I2c1 wrote, then read");
            kani::cover!(wl > 0 && rl == 0, "I2c1 wrote only");
            kani::cover!(wl == 0 && rl > 0, "I2c1 read only");
        }
        Err(I2cError::Txis) => kani::cover!(true, "I2c1 timed out waiting for TXIS"),
        Err(I2cError::Tc) => kani::cover!(true, "I2c1 timed out waiting for TC"),
        Err(I2cError::Rxne) => kani::cover!(true, "I2c1 timed out waiting for RXNE"),
        Err(I2cError::Stop) => kani::cover!(true, "I2c1 timed out waiting for STOPF"),
        Err(I2cError::Length) => kani::assert(false, "a transfer of at most two bytes was refused as too long"),
    }
}

/// Spi1's registers and its devices' chip selects as a transfer may touch them,
/// in order. `stage` is 0 before, 1 once TSIZE is set, 2 once the device is
/// selected, 3 once enabled, 4 once started, 5 once EOT is cleared, 6 once
/// disabled, 7 once deselected.
struct Spi1Spy {
    device: Spi1Device,
    out: [u8; 2],
    wl: usize,
    stage: u8,
    cr1: u32,
    tsize: u32,
    sr_reads: u32,
    rxp: bool,
    sent: usize,
    received: usize,
    touched: bool,
}

impl Spi1Spy {
    /// The device's chip select: its port, and its BSRR reset and set words.
    fn select(&self) -> (Block, u32, u32) {
        match self.device {
            Spi1Device::U4 => (Block::GpioA, 0x00010000, 0x00000001),
        }
    }
}

impl sealed::Sealed for Spi1Spy {}

impl Registers for Spi1Spy {
    fn read(&mut self, _: sealed::Token, block: Block, offset: usize) -> u32 {
        self.touched = true;
        kani::assert(block == Block::Spi1, "a Spi1 transfer read another block");
        if offset == 0x00 {
            if kani::any() { self.cr1 & !0x00000200 } else { self.cr1 }
        } else if offset == 0x14 {
            kani::assert(self.stage == 4, "SR polled outside the transfer");
            self.sr_reads += 1;
            let v: u32 = kani::any();
            self.rxp = v & 0x00000001 != 0;
            v
        } else {
            kani::assert(false, "a Spi1 transfer read a register it does not own");
            0
        }
    }
    fn write(&mut self, _: sealed::Token, block: Block, offset: usize, value: u32) {
        self.touched = true;
        let (port, select, deselect) = self.select();
        if block == port && offset == 0x18 && value == select {
            kani::assert(self.stage == 1, "the device was selected out of order");
            self.stage = 2;
        } else if block == port && offset == 0x18 && value == deselect {
            kani::assert(self.stage == 6, "the device was deselected before the peripheral was disabled");
            self.stage = 7;
        } else if block == Block::Spi1 && offset == 0x04 {
            kani::assert(self.stage == 0, "CR2 written out of order");
            kani::assert(self.cr1 & 0x00000001 == 0, "TSIZE written while the peripheral is enabled");
            self.tsize = value;
            self.stage = 1;
        } else if block == Block::Spi1 && offset == 0x00 {
            kani::assert(
                (value ^ self.cr1) & !(0x00000001 | 0x00000200) == 0,
                "CR1 changed beyond SPE and CSTART",
            );
            // `CSTART` is set-only: the enable may carry a stale one back.
            if self.stage == 2 {
                kani::assert(value & 0x00000001 != 0, "the peripheral was not enabled");
                self.stage = 3;
            } else if self.stage == 3 {
                kani::assert(
                    value & (0x00000001 | 0x00000200) == 0x00000001 | 0x00000200,
                    "the transfer was not started",
                );
                self.stage = 4;
            } else if self.stage == 5 {
                kani::assert(value & 0x00000001 == 0, "the peripheral was not disabled");
                self.stage = 6;
            } else {
                kani::assert(false, "CR1 written out of order");
            }
            self.cr1 = value;
        } else if block == Block::Spi1 && offset == 0x18 {
            kani::assert(self.stage == 4, "EOT cleared out of order");
            kani::assert(value == 0x00000008, "IFCR cleared more than EOTC");
            self.stage = 5;
        } else {
            kani::assert(false, "a Spi1 transfer wrote a register it does not own, or another device's chip select");
        }
    }
    fn read8(&mut self, _: sealed::Token, block: Block, offset: usize) -> u8 {
        self.touched = true;
        kani::assert(block == Block::Spi1 && offset == 0x30, "a byte read of anything but RXDR");
        kani::assert(self.stage == 4, "RXDR read outside the transfer");
        kani::assert(self.rxp, "RXDR read without RXP");
        self.rxp = false;
        self.received += 1;
        kani::any()
    }
    fn write8(&mut self, _: sealed::Token, block: Block, offset: usize, value: u8) {
        self.touched = true;
        kani::assert(block == Block::Spi1 && offset == 0x20, "a byte write to anything but TXDR");
        kani::assert(self.stage == 4, "TXDR written outside the transfer");
        let expected = if self.sent < self.wl { self.out[self.sent] } else { 0 };
        kani::assert(value == expected, "a frame is not the caller's byte, or a dummy is not 0x00");
        self.sent += 1;
        kani::assert(self.sent as u32 <= self.tsize, "more frames sent than TSIZE");
    }
}

/// A transfer of any device, up to two bytes out and three in (an identity
/// read is one and three) and any answers, with each wait bounded at two reads
/// of `SR`: selects that device before its first frame and deselects it after
/// the peripheral is disabled, also after a wait that expired; reads `RXDR`
/// only after `RXP`; and returns `Ok` only when every frame moved.
#[kani::proof]
#[kani::unwind(5)]
fn spi1_transfer_is_bounded_and_ordered() {
    let mut img = Image {
        rcc: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let gpioa = rcc.enable_gpioa(&mut img, board.gpioa).split();
    let pa5 = gpioa.pa5.into_spi1_sck(&mut img);
    let pa7 = gpioa.pa7.into_spi1_mosi(&mut img);
    let pa6 = gpioa.pa6.into_spi1_miso(&mut img);
    let pa0 = gpioa.pa0.into_output(&mut img);
    let mut bus = rcc
        .enable_spi1(&mut img, board.spi1)
        .init(&mut img, pa5, pa7, pa6, Spi1Selects { pa0 });
    let devices = [Spi1Device::U4];
    let pick: usize = kani::any();
    kani::assume(pick < devices.len());
    let device = devices[pick];
    // The state `init` and every transfer leave: disabled (`every_valid_sequence`,
    // and the end of this proof).
    let cr1: u32 = kani::any();
    kani::assume(cr1 & 0x00000001 == 0);
    let (wl, rl): (usize, usize) = (kani::any(), kani::any());
    kani::assume(wl <= 2 && rl <= 3);
    let out: [u8; 2] = kani::any();
    let mut back = [0u8; 3];
    let mut spy = Spi1Spy { device, out, wl, stage: 0, cr1, tsize: 0, sr_reads: 0, rxp: false, sent: 0, received: 0, touched: false };
    let spins = 2;
    let result = bus.transfer_within(&mut spy, device, &out[..wl], &mut back[..rl], spins);
    let frames = wl + rl;
    if frames == 0 {
        kani::assert(result == Err(SpiError::Length), "a transfer of nothing was not refused");
        kani::assert(!spy.touched, "a refused transfer touched a register");
        kani::cover!(true, "Spi1 refused a transfer of nothing");
        return;
    }
    kani::assert(spy.stage == 7, "a transfer did not end disabled and deselected");
    kani::assert(spy.tsize == frames as u32, "TSIZE is not the frames of the transfer");
    kani::assert(
        spy.sr_reads as usize <= frames * spins as usize,
        "a wait read SR more often than its bound",
    );
    match result {
        Ok(n) => {
            kani::assert(n == rl && spy.sent == frames && spy.received == frames, "Ok without every frame moved");
            kani::cover!(wl > 0 && rl > 0, "Spi1 wrote, then read");
            kani::cover!(wl == 1 && rl == 3, "Spi1 made an identity read's frames");
        }
        Err(SpiError::Rxp) => {
            kani::assert(spy.received < frames, "Rxp after every frame moved");
            kani::cover!(true, "Spi1 timed out waiting for RXP");
        }
        Err(SpiError::Length) => kani::assert(false, "a transfer of at most five frames was refused"),
    }
}

/// More frames than [`SPI_MAX_FRAMES`] are refused, and touch no register. The
/// bound fails the proof if a loop of the transfer is reached.
#[kani::proof]
#[kani::unwind(2)]
fn spi1_transfer_refuses_too_many_frames() {
    let mut img = Image {
        rcc: kani::any(),
        gpioa: kani::any(),
        gpiob: kani::any(),
        i2c1: kani::any(),
        spi1: kani::any(),
    };
    let board = Board::take().unwrap();
    let mut rcc = board.rcc;
    let gpioa = rcc.enable_gpioa(&mut img, board.gpioa).split();
    let pa5 = gpioa.pa5.into_spi1_sck(&mut img);
    let pa7 = gpioa.pa7.into_spi1_mosi(&mut img);
    let pa6 = gpioa.pa6.into_spi1_miso(&mut img);
    let pa0 = gpioa.pa0.into_output(&mut img);
    let mut bus = rcc
        .enable_spi1(&mut img, board.spi1)
        .init(&mut img, pa5, pa7, pa6, Spi1Selects { pa0 });
    let devices = [Spi1Device::U4];
    let pick: usize = kani::any();
    kani::assume(pick < devices.len());
    let device = devices[pick];
    // The state `init` and every transfer leave: disabled (`every_valid_sequence`,
    // and the end of this proof).
    let cr1: u32 = kani::any();
    kani::assume(cr1 & 0x00000001 == 0);
    let (wl, out) = (1, [0u8; 2]);
    let mut back = [0u8; SPI_MAX_FRAMES as usize];
    let mut spy = Spi1Spy { device, out, wl, stage: 0, cr1, tsize: 0, sr_reads: 0, rxp: false, sent: 0, received: 0, touched: false };
    let result = bus.transfer(&mut spy, device, &out[..wl], &mut back);
    kani::assert(result == Err(SpiError::Length), "a transfer of too many frames was not refused");
    kani::assert(!spy.touched, "a refused transfer touched a register");
    kani::cover!(true, "Spi1 refused too many frames");
}
